<script setup lang="ts">
import { Eye, Heart, ShoppingCart } from '@lucide/vue'
import BaseWhatsAppButton from './BaseWhatsAppButton.vue'
import type { StoreProduct, StorefrontPayload } from '#shared/types/storefront'
import { useStorefrontCatalog } from '~~/layers/storefront-core/app/composables/useStorefrontCatalog'
import { useStorefrontCommerce } from '~~/layers/storefront-core/app/composables/useStorefrontCommerce'
const props = defineProps<{ product: StoreProduct, storefront: StorefrontPayload }>()
const { money, productImage, usePlaceholder, discount } = useStorefrontCatalog(props.storefront)
const { addToCart, canPurchase, toggleWishlist, isWishlisted, busyProducts } = useStorefrontCommerce(props.storefront)
const requestUrl = useRequestURL()
const whatsappMessage = computed(() => `Olá! Tenho interesse no produto ${props.product.name}.\n${new URL(`/produto/${encodeURIComponent(props.product.slug)}`, requestUrl.origin).href}`)
const wished = computed(() => isWishlisted(props.product.id))
const busy = computed(() => busyProducts.value.includes(props.product.id))
const isSale = computed(() => Boolean(props.product.original_price && props.product.original_price > props.product.price))
const isNew = computed(() => props.product.id % 4 === 0 || props.product.id % 7 === 0)
const isBestSeller = computed(() => props.product.is_featured)
const views = computed(() => 70 + ((props.product.id * 37) % 280))
</script>

<template>
  <article class="retail-product card"><div class="product-media"><NuxtLink :to="`/produto/${product.slug}`"><img v-if="productImage(product)" :src="productImage(product)!" :alt="product.name" loading="lazy" @error="usePlaceholder"><img v-else src="/images/placeholders/product-default.png" alt="Imagem ilustrativa do produto" loading="lazy"></NuxtLink><div class="badge-stack"><span v-if="isNew" class="tag tag-new">Novo</span><span v-if="isSale" class="tag tag-sale">Promoção</span><span v-if="isBestSeller" class="tag tag-best">Mais vendido</span><span v-if="product.stock < 1" class="tag tag-out">Esgotado</span></div><span v-if="discount(product)" class="corner-discount">-{{ discount(product) }}%</span><span class="views"><Eye :size="13" />{{ views }}</span><button type="button" class="favorite btn btn-circle btn-sm" :class="wished ? 'btn-secondary' : 'btn-ghost bg-base-100'" :aria-label="wished ? 'Remover da lista de desejos' : 'Adicionar à lista de desejos'" :aria-pressed="wished" @click="toggleWishlist(product)"><Heart :size="16" :fill="wished ? 'currentColor' : 'none'"/></button></div><div class="product-content"><span class="category">{{ product.categories[0]?.name || 'Cuidados diários' }}</span><NuxtLink :to="`/produto/${product.slug}`"><h3>{{ product.name }}</h3></NuxtLink><p>{{ product.excerpt || (product.stock > 0 ? `${product.stock} unidades disponíveis` : 'Produto indisponível') }}</p><div class="product-price"><span><s v-if="product.original_price && product.original_price > product.price">{{ money(product.original_price) }}</s><strong>{{ money(product.price) }}</strong><small :class="{ low: product.stock > 0 && product.stock <= 5 }">{{ product.stock > 0 && product.stock <= 5 ? 'Estoque baixo' : 'à vista' }}</small></span><button v-if="canPurchase" type="button" class="btn btn-primary btn-sm" :disabled="product.stock<1 || busy" aria-label="Adicionar ao carrinho" @click="addToCart(product)"><span v-if="busy" class="loading loading-spinner loading-xs"></span><ShoppingCart v-else :size="16"/><em>{{ product.stock<1 ? 'Indisponível' : 'Adicionar ao carrinho' }}</em></button><BaseWhatsAppButton :phone="storefront.theme.contact_phone" variant="inline" :message="whatsappMessage" /></div></div></article>
</template>

<style scoped>
.retail-product{display:flex;min-width:0;flex-direction:column;border:1px solid #e5e7eb;border-radius:12px;background:#fff;overflow:hidden;transition:border-color .2s,box-shadow .2s,transform .2s}.retail-product:hover{border-color:#cbd5e1;box-shadow:0 18px 40px rgba(15,23,42,.08);transform:translateY(-2px)}.product-media{position:relative;padding:10px}.product-media>a{display:block;aspect-ratio:1.18/1;overflow:hidden;border-radius:9px;background:#f1f3f6}.product-media img{display:block;width:100%;height:100%;object-fit:contain;padding:10px;transition:transform .24s}.retail-product:hover img{transform:scale(1.035)}.badge-stack{position:absolute;left:18px;top:18px;z-index:2;display:grid;justify-items:start;gap:5px}.tag{display:inline-flex;height:20px;align-items:center;padding:0 8px;border-radius:999px;color:#fff;font-size:10px;font-weight:750;line-height:1;text-transform:uppercase}.tag-new{background:#41dc4b}.tag-sale{background:#ff4d22}.tag-best{background:#ff9f0a}.tag-out{background:#a3a3a3}.corner-discount{position:absolute;right:10px;top:10px;z-index:2;display:grid;width:58px;height:58px;place-items:start end;padding:9px 7px 0 0;background:linear-gradient(45deg,transparent 50%,#2563eb 50%);color:#fff;font-size:11px;font-weight:750}.views{position:absolute;right:18px;top:76px;z-index:2;display:inline-flex;height:24px;align-items:center;gap:4px;padding:0 8px;border-radius:999px;background:rgba(255,255,255,.9);color:#2563eb;font-size:11px;font-weight:650}.favorite{position:absolute;right:17px;bottom:17px;display:grid;width:34px;height:34px;place-items:center;border:1px solid #e5e7eb;border-radius:50%;background:#fff;color:#6b7280;box-shadow:none}.product-content{display:flex;flex:1;flex-direction:column;padding:7px 18px 18px}.category{color:var(--sf-primary);font-size:14px;font-weight:500;letter-spacing:0;text-transform:none}.product-content>a{color:var(--sf-ink);text-decoration:none}.product-content h3{min-height:45px;margin:7px 0 10px;font-size:15px;font-weight:650;line-height:1.45;text-wrap:pretty}.product-content p{min-height:34px;margin:0;color:#6b7280;font-size:14px;line-height:1.45}.product-price{display:grid;gap:12px;margin-top:auto;padding-top:14px}.product-price>span{display:flex;flex-wrap:wrap;align-items:end;gap:6px}.product-price s{color:#8a8f98;font-size:14px}.product-price strong{color:#111827;font-size:20px;font-weight:750;font-variant-numeric:tabular-nums;letter-spacing:-.02em}.product-price small{display:inline-flex;align-items:center;height:19px;padding:0 7px;border:1px solid #bbf7d0;border-radius:999px;color:#16a34a;font-size:10px;font-weight:650;text-transform:uppercase}.product-price small.low{border-color:#fecaca;background:#fff5f5;color:#ef4444}.product-price button,.product-price :deep(.whatsapp-button--inline){box-sizing:border-box;display:flex;width:100%;height:52px;min-height:52px;margin:0;align-items:center;justify-content:center;gap:8px;padding:8px 12px;border-radius:999px;box-shadow:none;font-family:inherit;font-size:14px;font-weight:600;line-height:18px;text-align:center}.product-price button>svg,.product-price :deep(.whatsapp-button--inline svg){width:18px;height:18px;flex:0 0 18px}.product-price button{border:1px solid var(--sf-primary);background:#fff;color:var(--sf-primary);transition:background .2s,color .2s,transform .2s}.product-price button:hover:not(:disabled){background:var(--sf-primary);box-shadow:none;color:#fff;transform:translateY(-1px)}.product-price button:disabled{cursor:not-allowed;opacity:.6}.product-price em{font-style:normal}.favorite[aria-pressed="true"]{color:#fff}@media(max-width:560px){.product-media{padding:8px}.product-content{padding:0 10px 12px}.product-content h3{font-size:14px}.product-content p{font-size:11px}.favorite,.views{display:none}.corner-discount{right:8px;top:8px}}
</style>
